+            let target = parent.join(name);
+            if target.exists() {
+                return runtime_error(&format!("a folder named {name} already exists in this location"));
+            }
+
+            let jot_dir = target.join(".jot");
+            if let Err(err) = fs::create_dir_all(&jot_dir) {
+                return runtime_undefined_error(&err);
+            }
+
+            let meta = VaultMeta {
+                name: name.clone(),
+                location: parent.to_string_lossy().into_owned(),
+                folder: String::new(),
+            };
+            if let Err(err) = meta.write(&jot_dir.join("data")) {
+                return runtime_undefined_error(&err);
+            }
+
+            index.insert(name.clone(), parent.to_string_lossy().into_owned());
+            if let Err(err) = paths.write_index(&index) {
+                return runtime_undefined_error(&err);
+            }
+
+            println!("vault {} created", blue(name));
