+    } else if !is_within(vault_root, &candidate) {
+        return Err(PathErrorKind::CrossesBounds);
+    }
+
+    if candidate == current_dir {
+        return Err(PathErrorKind::SameLocation);
+    }
+    if !candidate.exists() || !candidate.is_dir() {
+        return Err(PathErrorKind::CouldntFind);
+    }
+
+    Ok(candidate)
