    Move,
    Vmove,
    Config,
    Help,
}

#[derive(Clone, Copy)]
enum ItemKind {
    Vault,
    Note,
    Folder,
}

#[derive(Clone, Copy)]
enum ListMode {
    All,
    Note,
    Folder,
}

fn main() {
    process::exit(run());
}

fn run() -> i32 {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        eprint!("{TOP_HELP}");
        return 2;
    }

    if args.len() == 1 && is_help_flag(&args[0]) {
        print!("{TOP_HELP}");
        return 0;
    }

    if args[0] == "help" {
        return handle_help(&args[1..]);
    }

    let Some(command) = parse_command(&args[0]) else {
        return parse_error_found_argument(&args[0], &["executable <SUBCOMMAND>"]);
    };

    dispatch(command, &args[1..])
}

fn handle_help(args: &[String]) -> i32 {
    if args.is_empty() {
        print!("{TOP_HELP}");
        return 0;
    }

    let Some(command) = parse_help_target(&args[0]) else {
        return parse_error_unknown_subcommand(&args[0], &["executable <SUBCOMMAND>"]);
    };

    if args.len() > 1 {
        return parse_error_unknown_subcommand(&args[1], usage_lines(command));
    }

    print!("{}", help_text(command));
    0
}

fn dispatch(command: CommandKind, args: &[String]) -> i32 {
    if command != CommandKind::Help && args.iter().any(|arg| is_help_flag(arg)) {
        print!("{}", help_text(command));
        return 0;
    }

    match command {
        CommandKind::Vault => cmd_vault(args),
        CommandKind::Note => cmd_note(args),
        CommandKind::Folder => cmd_folder(args),
        CommandKind::Enter => cmd_enter(args),
        CommandKind::Open => cmd_open(args),
        CommandKind::Opdir => cmd_opdir(args),
        CommandKind::Chdir => cmd_chdir(args),
        CommandKind::List => cmd_list(args),
        CommandKind::Remove => cmd_remove(args),
        CommandKind::Rename => cmd_rename(args),
        CommandKind::Move => cmd_move(args),
        CommandKind::Vmove => cmd_vmove(args),
        CommandKind::Config => cmd_config(args),
        CommandKind::Help => handle_help(args),
    }
}

fn cmd_vault(args: &[String]) -> i32 {
    match args {
        [] => {
            let paths = Paths::from_env();
            let index = match paths.read_index_if_present() {
                Ok(index) => index,
                Err(err) => return runtime_undefined_error(&err),
            };
            print_vaults(&index, false);
            0
        }
        [flag] if flag == "-l" => {
            let paths = Paths::from_env();
            let index = match paths.read_index_if_present() {
                Ok(index) => index,
                Err(err) => return runtime_undefined_error(&err),
            };
            print_vaults(&index, true);
            0
        }
        [name] => parse_error_missing_arguments(&["<vault location>"], usage_lines(CommandKind::Vault)),
        [name, location] => {
            if invalid_name(name) {
                return runtime_error("invalid name");
            }

            let parent = PathBuf::from(location);
            if !parent.is_absolute() {
                return runtime_error("specified path isn't absolute");
            }

            let paths = Paths::from_env();
            let mut index = match paths.read_index() {
                Ok(index) => index,
                Err(err) => return runtime_undefined_error(&err),
            };

            if index.contains(name) {
                return runtime_error(&format!("vault {name} already exists"));
            }
            if !parent.exists() {
                return runtime_error("couldn't find the path specified");
            }
            if !parent.is_dir() {
                return runtime_undefined_error(&io::Error::from_raw_os_error(20));
            }

            let target = parent.join(name);
            if target.exists() {
                return runtime_error(&format!("a folder named {name} already exists in this location"));
            }

            let jot_dir = target.join(".jot");
            if let Err(err) = fs::create_dir_all(&jot_dir) {
                return runtime_undefined_error(&err);
            }

            let meta = VaultMeta {
                name: name.clone(),
                location: parent.to_string_lossy().into_owned(),
                folder: String::new(),
            };
            if let Err(err) = meta.write(&jot_dir.join("data")) {
                return runtime_undefined_error(&err);
            }

            index.insert(name.clone(), parent.to_string_lossy().into_owned());
            if let Err(err) = paths.write_index(&index) {
                return runtime_undefined_error(&err);
            }

            println!("vault {} created", blue(name));
            0
        }
        _ => parse_error_found_argument(&args[2], usage_lines(CommandKind::Vault)),
    }
}

