fn cmd_list(args: &[String]) -> i32 {
    let mode = match args {
        [] => ListMode::All,
        [kind] => match parse_list_mode(kind) {
            Some(mode) => mode,
            None => return parse_error_invalid_value(kind, "<item type>", "note, nt, folder, fd"),
        },
        _ => return parse_error_found_argument(&args[1], usage_lines(CommandKind::List)),
    };

    let paths = Paths::from_env();
    let Some(current) = load_current_vault(&paths) else {
        return runtime_error("not inside a vault");
    };

    println!("{}", current.header());

    let mut entries = Vec::new();
    let read_dir = match fs::read_dir(&current.current_dir) {
        Ok(read_dir) => read_dir,
        Err(err) => return runtime_undefined_error(&err),
    };

    for item in read_dir {
        let Ok(item) = item else {
            continue;
        };
        let path = item.path();
        let name = item.file_name().to_string_lossy().into_owned();

        match mode {
            ListMode::All => {
                if path.is_dir() {
                    if name != ".jot" {
                        entries.push(DisplayEntry::Folder(name));
                    }
                } else if let Some(note) = display_note_name(&path) {
                    entries.push(DisplayEntry::Note(note));
                }
            }
            ListMode::Note => {
                if let Some(note) = display_note_name(&path) {
                    entries.push(DisplayEntry::Note(note));
                }
            }
            ListMode::Folder => {
                if path.is_dir() {
                    entries.push(DisplayEntry::Folder(name));
                }
            }
        }
    }

    for (idx, entry) in entries.iter().enumerate() {
        let branch = if idx + 1 == entries.len() { "└──" } else { "├──" };
        println!("{branch} {}", entry.render());
    }

    0
}

fn cmd_remove(args: &[String]) -> i32 {
    if args.len() < 2 {
        let missing = if args.is_empty() {
            vec!["<item type>", "<name>"]
        } else {
            vec!["<name>"]
        };
        return parse_error_missing_arguments(&missing, usage_lines(CommandKind::Remove));
    }
    if args.len() > 2 {
        return parse_error_found_argument(&args[2], usage_lines(CommandKind::Remove));
    }

    let Some(kind) = parse_item_kind(&args[0]) else {
        return parse_error_invalid_value(&args[0], "<item type>", "vault, vl, note, nt, folder, fd");
    };
    let name = &args[1];
    if invalid_name(name) {
        return runtime_error("invalid name");
    }

    match kind {
        ItemKind::Vault => remove_vault(name),
        ItemKind::Note => remove_note(name),
        ItemKind::Folder => remove_folder(name),
    }
}

