fn cmd_config(args: &[String]) -> i32 {
    match args {
        [] => {
            let paths = Paths::from_env();
            let config = match paths.read_config() {
                Ok(config) => config,
                Err(err) => return runtime_undefined_error(&err),
            };
            launch_editor(&config.editor, &paths.config)
        }
        [kind] => {
            let Some(config_kind) = parse_config_kind(kind) else {
                return parse_error_invalid_value(kind, "<config type>", "editor, conflict");
            };

            let paths = Paths::from_env();
            let config = match paths.read_config() {
                Ok(config) => config,
                Err(err) => return runtime_undefined_error(&err),
            };

            match config_kind {
                ConfigKind::Editor => println!("editor: {}", blue(&config.editor)),
                ConfigKind::Conflict => println!(
                    "conflict: {}",
                    blue(if config.conflict { "true" } else { "false" })
                ),
            }
            0
        }
        [kind, value] => {
            let Some(config_kind) = parse_config_kind(kind) else {
                return parse_error_invalid_value(kind, "<config type>", "editor, conflict");
            };

            let paths = Paths::from_env();
            let mut config = match paths.read_config() {
                Ok(config) => config,
                Err(err) => return runtime_undefined_error(&err),
            };

            match config_kind {
                ConfigKind::Editor => config.editor = value.clone(),
                ConfigKind::Conflict => config.conflict = parse_conflict_value(value),
