fn remove_vault(name: &str) -> i32 {
    let paths = Paths::from_env();
    let mut index = match paths.read_index() {
        Ok(index) => index,
        Err(err) => return runtime_undefined_error(&err),
    };

    let Some(location) = index.get(name).map(str::to_string) else {
        return runtime_error(&format!("vault {name} doesn't exist"));
    };

    let root = PathBuf::from(location).join(name);
    if let Err(err) = fs::remove_dir_all(&root) {
        return runtime_undefined_error(&err);
    }

    index.remove(name);
    if let Err(err) = paths.write_index(&index) {
        return runtime_undefined_error(&err);
    }

    println!("vault {} removed", blue(name));
    0
}

