fn rename_vault(old: &str, new: &str) -> i32 {
    if invalid_name(old) || invalid_name(new) {
        return runtime_error("invalid name");
    }

    let paths = Paths::from_env();
    let mut index = match paths.read_index() {
        Ok(index) => index,
        Err(err) => return runtime_undefined_error(&err),
    };

    let Some(location) = index.get(old).map(str::to_string) else {
        return runtime_error(&format!("vault {old} doesn't exist"));
    };

    if index.contains(new) {
        return runtime_error(&format!("vault {new} already exists"));
    }

    let parent = PathBuf::from(&location);
    let old_root = parent.join(old);
    let new_root = parent.join(new);
    if let Err(err) = fs::rename(&old_root, &new_root) {
        return runtime_undefined_error(&err);
    }

    let meta_path = new_root.join(".jot").join("data");
    let mut meta = match VaultMeta::read(&meta_path) {
        Ok(meta) => meta,
        Err(err) => return runtime_undefined_error(&err),
    };
    meta.name = new.to_string();
    if let Err(err) = meta.write(&meta_path) {
        return runtime_undefined_error(&err);
    }

    index.remove(old);
    index.insert(new.to_string(), location);
    if index.current.as_deref() == Some(old) {
        index.current = Some(new.to_string());
    }
    if let Err(err) = paths.write_index(&index) {
        return runtime_undefined_error(&err);
    }

    println!("vault {} renamed to {}", blue(old), blue(new));
    0
}

fn rename_note(old: &str, new: &str) -> i32 {
    if invalid_name(old) || invalid_name(new) {
        return runtime_error("invalid name");
    }
    if old == new {
        return runtime_error("new name is same as old name");
    }

    let paths = Paths::from_env();
    let current = match load_current_vault(&paths) {
        Some(current) => current,
        None => return runtime_error("not inside a vault"),
    };

    let old_path = current.current_dir.join(note_file_name(old));
    if !old_path.exists() {
        return runtime_error(&format!("note {old} not found"));
    }
    let new_path = current.current_dir.join(note_file_name(new));
    if new_path.exists() && old_path != new_path {
        return runtime_error(&format!("a note named {new} already exists in this location"));
    }

    if let Err(err) = fs::rename(&old_path, &new_path) {
        return runtime_undefined_error(&err);
    }

    println!("note {} renamed to {}", blue(old), blue(new));
    0
}

fn rename_folder(old: &str, new: &str) -> i32 {
    if invalid_name(old) || invalid_name(new) {
        return runtime_error("invalid name");
    }
    if old == new {
        return runtime_error("new name is same as old name");
    }

    let paths = Paths::from_env();
    let current = match load_current_vault(&paths) {
        Some(current) => current,
        None => return runtime_error("not inside a vault"),
    };

    let old_path = current.current_dir.join(old);
    if !old_path.exists() {
        return runtime_error(&format!("folder {old} not found"));
    }
    let new_path = current.current_dir.join(new);
    if new_path.exists() {
        return runtime_error(&format!("a folder named {new} already exists in this location"));
    }

    match fs::rename(&old_path, &new_path) {
        Ok(_) => {
            println!("folder {} renamed to {}", blue(old), blue(new));
            0
        }
        Err(err) => runtime_undefined_error(&err),
    }
}

fn move_vault(name: &str, new_location: &str) -> i32 {
    if invalid_name(name) {
        return runtime_error("invalid name");
    }

    let destination_parent = PathBuf::from(new_location);
    if !destination_parent.is_absolute() {
        return runtime_error("specified path isn't absolute");
    }

    let paths = Paths::from_env();
    let mut index = match paths.read_index() {
        Ok(index) => index,
        Err(err) => return runtime_undefined_error(&err),
    };
    let Some(old_location) = index.get(name).map(str::to_string) else {
        return runtime_error(&format!("vault {name} doesn't exist"));
    };

    let old_parent = PathBuf::from(&old_location);
    if old_parent == destination_parent {
        return runtime_error("new location is same as old location");
    }

    let old_root = old_parent.join(name);
    let new_root = destination_parent.join(name);
    if new_root.exists() {
        return runtime_error(&format!("a folder named {name} already exists in this location"));
    }

    if let Err(err) = fs::rename(&old_root, &new_root) {
        return runtime_error(&lowercase_first(&err.to_string()));
    }

    let meta_path = new_root.join(".jot").join("data");
    let mut meta = match VaultMeta::read(&meta_path) {
        Ok(meta) => meta,
        Err(err) => return runtime_undefined_error(&err),
    };
    meta.location = destination_parent.to_string_lossy().into_owned();
    if let Err(err) = meta.write(&meta_path) {
        return runtime_undefined_error(&err);
    }

    index.insert(name.to_string(), destination_parent.to_string_lossy().into_owned());
    if let Err(err) = paths.write_index(&index) {
        return runtime_undefined_error(&err);
    }

    println!("vault {} moved", blue(name));
    0
}

