fn move_item_in_vault(name: &str, new_location: &str, kind: ItemKind) -> i32 {
    if invalid_name(name) {
        return runtime_error("invalid name");
    }

    let paths = Paths::from_env();
    let current = match load_current_vault(&paths) {
        Some(current) => current,
        None => return runtime_error("not inside a vault"),
    };

    let old_path = match kind {
        ItemKind::Note => current.current_dir.join(note_file_name(name)),
        ItemKind::Folder => current.current_dir.join(name),
        ItemKind::Vault => unreachable!(),
    };

    let destination_dir = match resolve_directory_target(&current.vault_root, &current.current_dir, new_location) {
        Ok(dir) => dir,
        Err(kind) => return runtime_error(kind.as_str()),
    };

    let new_path = match kind {
        ItemKind::Note => destination_dir.join(note_file_name(name)),
        ItemKind::Folder => destination_dir.join(name),
        ItemKind::Vault => unreachable!(),
    };

    if new_path == old_path {
        return runtime_error("new location is same as old location");
    }
    if new_path.exists() {
        let noun = match kind {
            ItemKind::Note => "note",
            ItemKind::Folder => "folder",
            ItemKind::Vault => unreachable!(),
        };
        return runtime_error(&format!("a {noun} named {name} already exists in this location"));
    }

    match fs::rename(&old_path, &new_path) {
        Ok(_) => {
            let noun = match kind {
                ItemKind::Note => "note",
                ItemKind::Folder => "folder",
                ItemKind::Vault => unreachable!(),
            };
            println!("{noun} {} moved", blue(name));
            0
        }
        Err(err) => runtime_error(&lowercase_first(&err.to_string())),
    }
}

fn vmove_note(name: &str, vault: &str) -> i32 {
    vmove_item(name, vault, ItemKind::Note)
}

fn vmove_folder(name: &str, vault: &str) -> i32 {
    vmove_item(name, vault, ItemKind::Folder)
}

fn vmove_item(name: &str, vault: &str, kind: ItemKind) -> i32 {
    if invalid_name(name) || invalid_name(vault) {
        return runtime_error("invalid name");
    }

    let paths = Paths::from_env();
    let current = match load_current_vault(&paths) {
        Some(current) => current,
        None => return runtime_error("not inside a vault"),
    };
    let index = match paths.read_index() {
        Ok(index) => index,
        Err(err) => return runtime_undefined_error(&err),
    };
    let Some(destination_parent) = index.get(vault) else {
        return runtime_error(&format!("vault {vault} doesn't exist"));
    };

    let old_path = match kind {
        ItemKind::Note => current.current_dir.join(note_file_name(name)),
        ItemKind::Folder => current.current_dir.join(name),
        ItemKind::Vault => unreachable!(),
    };
    let destination_root = PathBuf::from(destination_parent).join(vault);
    let new_path = match kind {
        ItemKind::Note => destination_root.join(note_file_name(name)),
        ItemKind::Folder => destination_root.join(name),
        ItemKind::Vault => unreachable!(),
    };

    if new_path.exists() && current.meta.name == vault && new_path == old_path {
        print!(
            "{} {} already exists in vault {}",
            match kind {
                ItemKind::Note => "note",
                ItemKind::Folder => "folder",
                ItemKind::Vault => unreachable!(),
            },
            name,
            vault
        );
        return runtime_error("new location is same as old location");
    }

    if new_path.exists() {
        return runtime_error(&format!(
            "a {} named {name} already exists in this location",
            match kind {
                ItemKind::Note => "note",
                ItemKind::Folder => "folder",
                ItemKind::Vault => unreachable!(),
            }
        ));
    }

    match fs::rename(&old_path, &new_path) {
        Ok(_) => {
            let noun = match kind {
                ItemKind::Note => "note",
                ItemKind::Folder => "folder",
                ItemKind::Vault => unreachable!(),
            };
            println!("{noun} {} moved to vault {}", blue(name), blue(vault));
            0
        }
        Err(err) => runtime_error(&lowercase_first(&err.to_string())),
    }
}

