}

fn load_current_vault(paths: &Paths) -> Option<CurrentVault> {
    let index = paths.read_index().ok()?;
    let current_name = index.current?;
    let parent = index.get(&current_name)?;
    let vault_root = PathBuf::from(parent).join(&current_name);
    let meta = VaultMeta::read(&vault_root.join(".jot").join("data")).ok()?;
    let current_dir = if meta.folder.is_empty() {
