#[derive(Clone, Copy)]
enum PathErrorKind {
    CouldntFind,
    CrossesBounds,
    SameLocation,
}

impl PathErrorKind {
    fn as_str(self) -> &'static str {
        match self {
            PathErrorKind::CouldntFind => "couldn't find the path specified",
            PathErrorKind::CrossesBounds => "path crosses the bounds of vault",
            PathErrorKind::SameLocation => "new location is same as old location",
        }
    }
}

fn resolve_directory_target(
    vault_root: &Path,
    current_dir: &Path,
    raw: &str,
) -> Result<PathBuf, PathErrorKind> {
    let raw_path = Path::new(raw);
    let candidate = if raw_path.is_absolute() {
        normalize_path(raw_path)
    } else {
        normalize_path(&current_dir.join(raw_path))
    };

    if raw_path.is_absolute() {
        if !candidate.exists() {
            return Err(PathErrorKind::CouldntFind);
        }
        if !is_within(vault_root, &candidate) {
            return Err(PathErrorKind::CrossesBounds);
        }
    } else if !is_within(vault_root, &candidate) {
        return Err(PathErrorKind::CrossesBounds);
    }

    if candidate == current_dir {
        return Err(PathErrorKind::SameLocation);
    }
    if !candidate.exists() || !candidate.is_dir() {
        return Err(PathErrorKind::CouldntFind);
    }

    Ok(candidate)
}

fn normalize_path(path: &Path) -> PathBuf {
    let absolute = path.is_absolute();
    let mut parts: Vec<OsString> = Vec::new();

    for component in path.components() {
        match component {
            Component::RootDir => {}
            Component::CurDir => {}
            Component::ParentDir => {
                if !parts.is_empty() {
                    parts.pop();
                } else if !absolute {
                    parts.push(OsString::from(".."));
                }
            }
            Component::Normal(part) => parts.push(part.to_os_string()),
            Component::Prefix(prefix) => parts.push(prefix.as_os_str().to_os_string()),
        }
    }

    let mut out = if absolute {
        PathBuf::from("/")
    } else {
        PathBuf::new()
    };

    for part in parts {
        out.push(part);
    }
    out
}

fn is_within(root: &Path, candidate: &Path) -> bool {
    candidate == root || candidate.starts_with(root)
}

fn relative_folder(root: &Path, path: &Path) -> String {
    if path == root {
        return String::new();
    }

    path.strip_prefix(root)
        .ok()
        .map(|value| value.to_string_lossy().replace('\\', "/"))
        .unwrap_or_default()
}

enum DisplayEntry {
    Note(String),
    Folder(String),
}

impl DisplayEntry {
    fn render(&self) -> String {
        match self {
            DisplayEntry::Note(name) => blue(name),
            DisplayEntry::Folder(name) => name.clone(),
        }
    }
}

