    pub fn read(path: &Path) -> io::Result<Self> {
        let text = fs::read_to_string(path)?;
        let mut config = Self::default();

        for line in text.lines() {
            let trimmed = line.trim();
            if let Some(value) = trimmed.strip_prefix("editor = ") {
                config.editor = parse_literal(value).unwrap_or_else(|| "nvim".to_string());
            } else if let Some(value) = trimmed.strip_prefix("conflict = ") {
                config.conflict = value.trim() == "true";
            }
        }

        Ok(config)
    }

    pub fn write(&self, path: &Path) -> io::Result<()> {
        let mut out = String::new();
        out.push_str("editor = ");
        out.push_str(&quote_literal(&self.editor));
        out.push('\n');
        out.push_str("conflict = ");
        out.push_str(if self.conflict { "true" } else { "false" });
        out.push('\n');
