pub mod config;

use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

pub use config::Config;

#[derive(Clone, Debug)]
pub struct Paths {
    pub config: PathBuf,
    pub vaults: PathBuf,
}

#[derive(Clone, Debug, Default)]
pub struct VaultIndex {
    pub current: Option<String>,
    pub vaults: Vec<(String, String)>,
}

#[derive(Clone, Debug)]
pub struct VaultMeta {
    pub name: String,
    pub location: String,
    pub folder: String,
}

impl Paths {
    pub fn from_env() -> Self {
        let home = env::var_os("HOME")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("."));

        let config_root = env::var_os("XDG_CONFIG_HOME")
            .map(PathBuf::from)
            .unwrap_or_else(|| home.join(".config"));
        let data_root = env::var_os("XDG_DATA_HOME")
            .map(PathBuf::from)
            .unwrap_or_else(|| home.join(".local").join("share"));

        Self {
            config: config_root.join("jot").join("config"),
            vaults: data_root.join("jot").join("vaults"),
        }
    }

    pub fn bootstrap(&self) -> io::Result<()> {
        if let Some(parent) = self.config.parent() {
            fs::create_dir_all(parent)?;
        }
        if let Some(parent) = self.vaults.parent() {
            fs::create_dir_all(parent)?;
        }

        if !self.config.exists() {
            Config::default().write(&self.config)?;
        }
        if !self.vaults.exists() {
            fs::write(&self.vaults, "[vaults]\n")?;
        }
        Ok(())
    }

    pub fn read_config(&self) -> io::Result<Config> {
        self.bootstrap()?;
        Config::read(&self.config)
    }

    pub fn write_config(&self, config: &Config) -> io::Result<()> {
        self.bootstrap()?;
        config.write(&self.config)
    }

    pub fn read_index(&self) -> io::Result<VaultIndex> {
        self.bootstrap()?;
        self.read_index_if_present()
    }

    pub fn read_index_if_present(&self) -> io::Result<VaultIndex> {
        if !self.vaults.exists() {
            return Ok(VaultIndex::default());
        }
        let text = fs::read_to_string(&self.vaults)?;
        Ok(parse_vault_index(&text))
    }

    pub fn write_index(&self, index: &VaultIndex) -> io::Result<()> {
        self.bootstrap()?;
        let mut out = String::new();
        if let Some(current) = &index.current {
            out.push_str("current = ");
            out.push_str(&quote_literal(current));
            out.push_str("\n\n");
        }
        out.push_str("[vaults]\n");
        for (name, location) in &index.vaults {
            out.push_str(name);
            out.push_str(" = ");
            out.push_str(&quote_literal(location));
            out.push('\n');
        }
        fs::write(&self.vaults, out)
    }
}

impl VaultIndex {
    pub fn get(&self, name: &str) -> Option<&str> {
        self.vaults
            .iter()
            .find(|(key, _)| key == name)
            .map(|(_, value)| value.as_str())
    }

    pub fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    pub fn insert(&mut self, name: String, location: String) {
        if let Some((_, value)) = self.vaults.iter_mut().find(|(key, _)| *key == name) {
            *value = location;
            return;
        }
        self.vaults.push((name, location));
    }

    pub fn remove(&mut self, name: &str) {
        self.vaults.retain(|(key, _)| key != name);
        if self.current.as_deref() == Some(name) {
            self.current = None;
        }
    }
}

impl VaultMeta {
    pub fn read(path: &Path) -> io::Result<Self> {
        let text = fs::read_to_string(path)?;
        let mut meta = Self {
            name: String::new(),
            location: String::new(),
            folder: String::new(),
        };

        for line in text.lines() {
            let trimmed = line.trim();
            if let Some(value) = trimmed.strip_prefix("name = ") {
                meta.name = parse_literal(value).unwrap_or_default();
            } else if let Some(value) = trimmed.strip_prefix("location = ") {
                meta.location = parse_literal(value).unwrap_or_default();
            } else if let Some(value) = trimmed.strip_prefix("folder = ") {
                meta.folder = parse_literal(value).unwrap_or_default();
            }
        }

        Ok(meta)
    }

    pub fn write(&self, path: &Path) -> io::Result<()> {
        let mut out = String::new();
        out.push_str("name = ");
        out.push_str(&quote_literal(&self.name));
        out.push('\n');
        out.push_str("location = ");
        out.push_str(&quote_literal(&self.location));
        out.push('\n');
        out.push_str("folder = ");
        out.push_str(&quote_literal(&self.folder));
        out.push('\n');
        out.push_str("history = []\n");
        fs::write(path, out)
    }
}

pub fn parse_literal(input: &str) -> Option<String> {
    let trimmed = input.trim();
    if !(trimmed.starts_with('\'') && trimmed.ends_with('\'')) {
        return None;
    }
    let inner = &trimmed[1..trimmed.len().saturating_sub(1)];
    Some(inner.replace("''", "'"))
}

pub fn quote_literal(value: &str) -> String {
    format!("'{}'", value.replace('\'', "''"))
}

fn parse_vault_index(text: &str) -> VaultIndex {
    let mut index = VaultIndex::default();
    let mut in_vaults = false;

    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        if trimmed == "[vaults]" {
            in_vaults = true;
            continue;
        }

        if let Some(value) = trimmed.strip_prefix("current = ") {
            index.current = parse_literal(value);
            continue;
        }

        if !in_vaults {
            continue;
        }

        if let Some((name, value)) = trimmed.split_once('=') {
            if let Some(location) = parse_literal(value.trim()) {
                index
                    .vaults
                    .push((name.trim().to_string(), location));
            }
        }
    }

    index
}

